  1824  MqttProp* MqttProps_Add(MqttProp **head)
  1825  {
  1826      MqttProp *new_prop = NULL, *prev = NULL, *cur;
  1827  #ifndef WOLFMQTT_DYN_PROP
  1828      int i;
  1829  #endif
  1830
  1831      if (head == NULL) {
  1832          return NULL;
  1833      }
  1834
  1835  #if !defined(WOLFMQTT_DYN_PROP) && defined(WOLFMQTT_MULTITHREAD)
  1836      if (wm_SemLock(&clientPropStack_lock) != 0) {
  1837          return NULL;
  1838      }
  1839  #endif
  1840
  1841      cur = *head;
  1842
  1843      /* Find the end of the parameter list */
  1844      while (cur != NULL) {
  1845          prev = cur;
  1846          cur = cur->next;
  1847      };
  1848
  1849  #ifndef WOLFMQTT_DYN_PROP
  1850      /* Find a free element */
  1851      for (i = 0; i < MQTT_MAX_PROPS; i++) {
  1852          if (clientPropStack[i].type == MQTT_PROP_NONE) {
  1853              /* Found one */
  1854              new_prop = &clientPropStack[i];
  1855              XMEMSET(new_prop, 0, sizeof(MqttProp));
  1856              break;
  1857          }
  1858      }
  1859  #else
  1860      /* Allocate a new prop */
  1861      new_prop = WOLFMQTT_MALLOC(sizeof(MqttProp));
  1862      if (new_prop != NULL) {
  1863          XMEMSET(new_prop, 0, sizeof(MqttProp));
  1864      }
  1865  #endif
  1866
  1867      if (new_prop != NULL) {
  1868          /* set placeholder until caller sets it to a real type */
  1869          new_prop->type = MQTT_PROP_TYPE_MAX;
  1870          if (prev == NULL) {
  1871              /* Start a new list */
  1872              *head = new_prop;
  1873          }
  1874          else {
  1875              /* Add to the existing list */
  1876              prev->next = new_prop;
  1877          }
  1878      }
  1879      else {
  1880          /* Could not allocate property */
  1881          (void)MQTT_TRACE_ERROR(MQTT_CODE_ERROR_PROPERTY);
  1882      }
  1883
  1884  #if !defined(WOLFMQTT_DYN_PROP) && defined(WOLFMQTT_MULTITHREAD)
  1885      (void)wm_SemUnlock(&clientPropStack_lock);
  1886  #endif
  1887
  1888      return new_prop;
  1889  }
